package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.TypedFields.require;
import java.util.*;
import org.apache.commons.codec.digest.DigestUtils;
/** Mapping diagnostics and reviewed snapshot replay; destination application remains atomic. */
final class MigrationRecovery {
 private MigrationRecovery() {}
 static Map<String,Object> job(Store.Db db,String id)throws Exception{Service.requireAccountAdministrator(db,db.viewerId);var job=TransferJobs.job(db,id);require(Set.of("review","applied","cutover").contains(object(job.get("detail")).get("status")),"Finish source fetching before recovery diagnostics");for(Object value:object(object(job.get("definition")).get("tables")).values()){var schema=Service.schema(db,object(value).get("target").toString());RecordPolicy.read(db,schema);RecordPolicy.require(schema,"create",db.viewerRole);}return job;}
 static Map<String,Object> page(Store.Db db,String id,Map<String,String> args)throws Exception{
  require(Set.of("table","after").containsAll(args.keySet()),"Use table and after only");var job=job(db,id);var tables=object(object(job.get("definition")).get("tables"));String table=args.getOrDefault("table",tables.keySet().iterator().next()),after=args.getOrDefault("after","");require(tables.containsKey(table) && after.matches("(?:[0-9a-f]{32})?"),"Choose a mapped table and source-ID cursor");var mapping=object(tables.get(table));var rows=db.all("SELECT source_id,data FROM os_transfer_item WHERE job_id=? AND source_table=? AND source_id>? ORDER BY source_id LIMIT 101",id,table,after);Object next=rows.size()>100?rows.get(99).get("source_id"):null;if(rows.size()>100)rows.removeLast();var results=new ArrayList<Map<String,Object>>();for(var row:rows){var item=map("source_id",row.get("source_id"),"status","mapping_valid","error",null,"mapped",null);try{item.put("mapped",TransferApply.mapped(db,mapping,object(row.get("data"))));}catch(Failure invalid){item.put("status","mapping_error");item.put("error",invalid.getMessage());}results.add(item);}return map("job_id",id,"source_url",job.get("source_url"),"state",object(job.get("detail")).get("status"),"tables",tables,"source_table",table,"target_table",mapping.get("target"),"rows",results,"next_after",next,"review",null,"child_job","","replays",object(job.get("detail")).getOrDefault("mapping_replays",map()),"replay_of",object(job.get("detail")).getOrDefault("replay_of",""));
 }
 static Map<String,Object> proposal(Store store,Store.Db db,Map<String,Object> job,Object input)throws Exception{
  var original=object(job.get("definition"));var replacement=object(input);var tables=object(original.get("tables"));require(replacement.keySet().equals(tables.keySet()),"Preserve the exact source table selection");for(var entry:replacement.entrySet()){var mapping=object(entry.getValue());var before=object(tables.get(entry.getKey()));require(Objects.equals(mapping.get("target"),before.get("target")),"Preserve each destination table");var fields=object(mapping.get("fields"));var selected=new HashSet<>(object(before.get("fields")).values());selected.addAll(List.of("sys_id","number","sys_created_on","sys_created_by","sys_updated_on","sys_updated_by"));require(selected.containsAll(fields.values()),"A new source field requires a fresh fetch");var schema=Service.schema(db,before.get("target").toString());require(object(schema.get("fields")).keySet().containsAll(fields.keySet()),"Choose existing destination fields");}var proposed=new LinkedHashMap<>(original);proposed.put("tables",replacement);return TransferJobs.definition(proposed,store.migrationOrigins);
 }
 static Map<String,Object> review(Store store,Store.Db db,Map<String,Object> job,Object mappings)throws Exception{
  var state=object(job.get("detail"));require(state.get("status").equals("review"),"Only unapplied staged migrations can be replayed");long generation=TransferJobs.generation(db,job.get("source_url").toString());if(((Number)state.get("generation")).longValue()!=generation)throw new Failure(409,"A newer migration applied; fetch a fresh synchronization");var plan=proposal(store,db,job,mappings);var schemas=map();for(Object entry:object(plan.get("tables")).values()){String target=object(entry).get("target").toString();schemas.put(target,Service.schema(db,target));}var snapshots=new ArrayList<Map<String,Object>>();long characters=0,bytes=0;for(var row:db.all("SELECT source_table,source_id,data,content FROM os_transfer_item WHERE job_id=? ORDER BY source_table,source_id",job.get("job_id"))){String data=JSON.writeValueAsString(row.get("data"));characters+=data.length();byte[] content=(byte[])row.get("content");if(content!=null)bytes+=content.length;snapshots.add(map("table",row.get("source_table"),"id",row.get("source_id"),"data_hash",DigestUtils.sha256Hex(data),"file_hash",content==null?"":DigestUtils.sha256Hex(content)));}require(snapshots.size()<=10000 && characters<=50L*1024*1024 && bytes<=50L*1024*1024,"Replay snapshot exceeds migration limits");String hash=DigestUtils.sha256Hex(JSON.writeValueAsString(snapshots));String proof=DigestUtils.sha256Hex("migration-replay-v1:"+JSON.writeValueAsString(map("actor",db.viewerId,"authority",db.one("SELECT auth_revision FROM os_user WHERE user_id=?",db.viewerId),"job",job,"plan",plan,"schemas",schemas,"generation",generation,"snapshot",hash)));return map("plan",plan,"review",proof,"snapshot_hash",hash,"rows",snapshots.size(),"json_characters",characters,"attachment_bytes",bytes,"source_created",job.get("created"));
 }
 static Map<String,Object> command(Store store,Store.Db db,String id,Object input)throws Exception{
  var job=job(db,id);var body=object(input);String operation=WorkJobs.text(body.get("operation"),12);require(Set.of("review","create").contains(operation),"Choose review or create");boolean creating=operation.equals("create");require(body.keySet().equals(creating?Set.of("operation","tables","review","confirm","key"):Set.of("operation","tables")),"Provide only the reviewed replay fields");var state=object(job.get("detail"));var replays=object(state.getOrDefault("mapping_replays",map()));String key="";if(creating){key=WorkJobs.text(body.get("key"),32);require(key.matches("[0-9a-f]{32}"),"Use a 32-character replay key");require(Boolean.TRUE.equals(body.get("confirm")),"Confirm the exact staged replay");ServiceNowSource.origin(job.get("source_url").toString(),store.migrationOrigins);if(replays.containsKey(key)){var previous=object(replays.get(key));if(!previous.get("tables").equals(body.get("tables")) || !previous.get("review").equals(body.get("review")))throw new Failure(409,"Replay key identifies another reviewed proposal");var result=page(db,id,Map.of());result.put("child_job",previous.get("child_job"));return result;}}
  var reviewed=review(store,db,job,body.get("tables"));if(!creating){var result=page(db,id,Map.of());result.put("review",reviewed);return result;}if(!reviewed.get("review").equals(body.get("review")))throw new Failure(409,"Source, mapping or authority changed; review again");require(replays.size()<20 && db.count("SELECT COUNT(*) FROM os_transfer_job")<1000,"Replay job capacity reached");var child=TransferJobs.create(db,reviewed.get("plan"),db.viewerId,store.migrationOrigins);String childId=child.get("job_id").toString();db.update("INSERT INTO os_transfer_item(job_id,source_table,source_id,data,content) SELECT ?,source_table,source_id,data,content FROM os_transfer_item WHERE job_id=?",childId,id);var childState=object(child.get("detail"));childState.put("status","review");childState.put("phase",TransferJobs.phases(object(child.get("definition"))).size());childState.put("replay_of",id);childState.put("snapshot_hash",reviewed.get("snapshot_hash"));TransferJobs.save(db,childId,childState);replays.put(key,map("child_job",childId,"tables",body.get("tables"),"review",body.get("review"),"snapshot_hash",reviewed.get("snapshot_hash"),"created",now()));state.put("mapping_replays",replays);TransferJobs.save(db,id,state);SecurityEvents.record(db,db.viewerId,db.viewerId,"migration.replayed",map("source_job",id,"child_job",childId,"rows",reviewed.get("rows"),"snapshot_hash",reviewed.get("snapshot_hash")));var result=page(db,id,Map.of());result.put("child_job",childId);return result;
 }
}
